#include <algorithm>
#include <cstdio>
#include <vector>
static int cmpint(const int& a, const int& b){ return a<b?-1:(a>b?1:0); }
static bool cmpbool(const int& a, const int& b){ return a<b; }
int main(){
    std::vector<int> v{5,7,3};
    std::sort(v.begin(), v.end(), cmpint);
    printf("%d %d %d\n", v[0],v[1],v[2]);
    std::vector<int> w{5,7,3};
    std::sort(w.begin(), w.end(), cmpbool);
    printf("%d %d %d\n", w[0],w[1],w[2]);
    std::vector<int> x{5,7,3};
    std::sort(x.begin(), x.end(), [](const int&a,const int&b){return a<b;});
    printf("%d %d %d\n", x[0],x[1],x[2]);
}
EOF
g++ -O0 -g -std=c++17 /tmp/dbg5.cpp -o /tmp/dbg5 && /tmp/dbg5
